export type Category = { id: string; name: string; icon: React.ReactNode; };

export type PackagingVariant = {
  name: string;
  catalogueNumber: string;
  units: string;
  format?: string;
};

export type KitItem = {
  name: string;
  description: string;
  catalogueNumber?: string;
};

export type FeatureCard = {
  title: string;
  body: string;
};

export type DetailSection = {
  title: string;
  body?: string;
  items?: string[];
};

export type Product = {
  id: string; name: string; brand: string; category: string;
  subcategory?: string; description: string; featured?: boolean; tags?: string[];
  image?: string;
  heroBg?: string;
  subtitle?: string;
  gallery?: string[];
  specSheet?: string;
  brochure?: string;
  kits?: KitItem[];
  featureCards?: FeatureCard[];  // structured title+body pairs for the feature card grid
  detailSections?: DetailSection[];
  highlights?: string[]; features?: string[]; applications?: string[];
  specs?: Record<string, string>; catalogueNumber?: string;
  packaging?: PackagingVariant[];
  relatedProducts?: string[];
};

export type Brand = {
  id: string; name: string; short: string; blurb: string; accent: string;
  logo?: string;      // URL to brand logo image (fetched client-side)
  longBlurb?: string; // Extended description for the mega menu brand panel
  founded?: string;
  hq?: string;
  website?: string;
};

